import okhttp3.*
import okhttp3.logging.HttpLoggingInterceptor
import java.util.concurrent.TimeUnit

class ApiClient {
    private val client: OkHttpClient

    init {
        // 1. Logger konfigurieren
        val logging = HttpLoggingInterceptor().apply {
            level = HttpLoggingInterceptor.Level.BODY
        }

        // 2. Retry Interceptor (Einfaches Beispiel: 3 Versuche bei 5xx Fehlern)
        val retryInterceptor = RetryInterceptor(maxAttempts = 3)

        // 3. OkHttpClient Builder
        client = OkHttpClient.Builder()
            // --- TIMEOUTS SETZEN ---
            .connectTimeout(10, TimeUnit.SECONDS)     // Zeit bis zum Verbindungsstart
            .readTimeout(30, TimeUnit.SECONDS)        // Zeit bis zum ersten Byte
            .writeTimeout(30, TimeUnit.SECONDS)       // Zeit bis zum Senden fertig ist
            .callTimeout(60, TimeUnit.SECONDS)        // Gesamtdauer des Calls

            // --- PARALLELITÄT (CONNECTION POOL) ---
            // Standardmäßig erlaubt OkHttp viele parallele Verbindungen pro Host.
            // Wir können sie explizit setzen (Default: 5 Idle Connections, 5 Min KeepAlive)
            .connectionPool(ConnectionPool(
                maxIdleConnections = 10,      // Max parallele leere Verbindungen
                keepAliveDuration = 5, 
                timeUnit = TimeUnit.MINUTES
            ))

            // --- RETRIES HINZUFÜGEN ---
            .addInterceptor(retryInterceptor)
            .addInterceptor(logging)

            .build()
    }

    fun executeRequest(url: String): String {
        val request = Request.Builder()
            .url(url)
            .get()
            .build()

        return client.newCall(request).execute().use { response ->
            if (!response.isSuccessful) throw IOException("Fehler: ${response.code}")
            response.body?.string() ?: ""
        }
    }
}

// Einfacher Retry Interceptor
class RetryInterceptor(private val maxAttempts: Int) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        var attempt = 0
        var lastException: Exception? = null

        while (attempt < maxAttempts) {
            try {
                val response = chain.proceed(chain.request())

                // Nur bei Server-Fehlern (5xx) oder Netzwerkproblemen neu versuchen
                if (response.code >= 500 || !response.isSuccessful) {
                    response.close()
                    attempt++
                    continue
                }
                return response
            } catch (e: Exception) {
                lastException = e
                attempt++
            }
        }

        throw lastException ?: RuntimeException("Retry fehlgeschlagen")
    }
}

