    implementation 'com.fasterxml.jackson.core:jackson-databind:2.16.1'

    // --- XML Parsing & Mapping ---
    // Jackson kann auch XML parsen (oft einfacher als JAXB zu konfigurieren)
    implementation 'com.fasterxml.jackson.dataformat:jackson-dataformat-xml:2.16.1'

    // --- XML Validierung (Schema/XSD) ---
    // Xerces wird benötigt, um Schemas gegen das XML zu prüfen
    implementation 'org.apache.xerces:xercesImpl:2.12.2'

    // --- Testing ---
    testImplementation 'org.junit.jupiter:junit-jupiter:5.10.1'
}

tasks.named('test') {
    useJUnitPlatform()
}

