// build.gradle

plugins {
    id 'java'
    id 'application'
}

// Projekt-Konfiguration
group = 'com.example.officeexport'
version = '1.0.0'

// Java-Version festlegen (z.B. 17 oder 21)
java {
    sourceCompatibility = JavaVersion.VERSION_17
    targetCompatibility = JavaVersion.VERSION_17
}

repositories {
    mavenCentral()
}

dependencies {
    // 1. Excel Schreiben (Apache POI)
    // poi-ooxml benötigt auch die Basis-Poi Bibliothek
    implementation 'org.apache.poi:poi-ooxml:5.2.5'

    // 2. CSV Einlesen mit Sonderzeichen (OpenCSV)
    // OpenCSV unterstützt Encoding und komplexe Trennzeichen gut
    implementation 'com.opencsv:opencsv:5.9'

    // 3. PDF Erstellen (Apache PDFBox - Lizenzfreundlich Apache 2.0)
    // Alternativ: iText7 (stärker, aber Lizenzbedingungen beachten)
    implementation 'org.apache.pdfbox:pdfbox:2.0.30'
}

// Anwendungskonfiguration
application {
    // Hier muss der Name deiner Hauptklasse stehen (ohne .java Extension)
    // Beispiel: mainClass = 'com.example.officeexport.MainApp'
    mainClass = 'dein.paket.Hauptklasse' 
}

// JVM Argumente für UTF-8 Unterstützung (Wichtig für Sonderzeichen!)
tasks.named('run') {
    jvmArgs '-Dfile.encoding=UTF-8'
}

// Optional: JAR mit allen Abhängigkeiten erstellen (Fat Jar)
// Wenn du das Tool als einzelne ausführbare Datei verteilen willst
jar {
    manifest {
        attributes(
            'Main-Class': application.mainClass.get()
        )
    }
    duplicatesStrategy = DuplicatesStrategy.EXCLUDE
}

