dependencies {
    // JSON: nested configs → Java-Objekte
    implementation 'com.fasterxml.jackson.core:jackson-databind:2.17.2'
    implementation 'com.fasterxml.jackson.core:jackson-core:2.17.2'
    implementation 'com.fasterxml.jackson.core:jackson-annotations:2.17.2'
    // Optional: Java 8 Date/Time, Optional, etc.
    implementation 'com.fasterxml.jackson.datatype:jackson-datatype-jsr310:2.17.2'
    implementation 'com.fasterxml.jackson.datatype:jackson-datatype-jdk8:2.17.2'

    // XML: Unmarshalling → Java-Objekte + Jackson-XML
    implementation 'com.fasterxml.jackson.dataformat:jackson-dataformat-xml:2.17.2'
    implementation 'org.codehaus.woodstox:woodstox-core:6.6.2'

    // JAXB (falls du klassisches Schema-Binding / Annotations willst)
    implementation 'jakarta.xml.bind:jakarta.xml.bind-api:4.0.2'
    implementation 'org.glassfish.jaxb:jaxb-runtime:4.0.5'

    // XML-Schema-Validierung (XSD) – API steckt im JDK, Helper optional
    // Für bequemes Validieren vor dem Unmarshalling reicht das JDK (javax.xml.validation)

    // Logging (sinnvoll bei Config-Parsing)
    implementation 'org.slf4j:slf4j-api:2.0.16'
    runtimeOnly 'ch.qos.logback:logback-classic:1.5.8'

    // Tests
    testImplementation 'org.junit.jupiter:junit-jupiter:5.11.0'
    testImplementation 'org.assertj:assertj-core:3.26.3'
    testRuntimeOnly 'org.junit.platform:junit-platform-launcher'
}

